/* @autogenerated */
import { Injectable, Injector, runInInjectionContext } from '@angular/core';
import {
  ActivatedRouteSnapshot,
  GuardResult,
  Params,
  PRIMARY_OUTLET,
  Route,
  Router,
  RouterStateSnapshot,
  UrlSegment,
} from '@angular/router';
import { catchError, concat, defer, first, from, isObservable, map, Observable, of, take } from 'rxjs';

/** Ruta de la configuración que casa con un tramo de la URL, con el snapshot que reciben sus guards. */
interface MatchedRoute {
  route: Route;
  snapshot: ActivatedRouteSnapshot;
}

type GuardMethod = 'canActivate' | 'canActivateChild';

@Injectable({
  providedIn: 'root',
})
export class RouteAccessService {
  constructor(
    private readonly router: Router,
    private readonly injector: Injector,
  ) {}

  /**
   * Indica si se podría navegar a `url` evaluando los guards como lo haría el router: de la raíz a la hoja,
   * primero los `canActivateChild` de los ancestros y luego el `canActivate` de cada ruta. Los guards se
   * ejecutan en orden y se para en el primero que no deja pasar. Cada guard recibe el snapshot de su ruta,
   * con su `data` y los parámetros de la URL (los de los padres incluidos).
   */
  checkRouteGuards(url: string): Observable<boolean> {
    const chain = this.matchChain(url.split('/'), this.router.config, {});
    if (!chain.length) {
      // Si no se encuentra ninguna ruta, no es accesible
      return of(false);
    }
    const state = { url: '/' + url, root: chain[0].snapshot } as RouterStateSnapshot;
    const checks = chain.flatMap((matched, index) => [
      ...chain
        .slice(0, index)
        .flatMap((ancestor) => ancestor.route.canActivateChild ?? [])
        .map((guard) => () => this.runGuard(guard, 'canActivateChild', matched.snapshot, state)),
      ...(matched.route.canActivate ?? []).map(
        (guard) => () => this.runGuard(guard, 'canActivate', matched.snapshot, state),
      ),
    ]);
    return concat(...checks.map((check) => defer(check).pipe(take(1)))).pipe(
      // El primer resultado que no sea true decide; si todos pasan (o no hay guards), es accesible
      first((result) => result !== true, true as GuardResult),
      map((result) => result === true),
      catchError(() => of(false)),
    );
  }

  // Método para verificar si la URL coincide con la ruta activa
  isUrlActive(url: string): boolean {
    const route = this.matchChain(url.split('/'), this.router.config, {}).at(-1)?.route;

    if (!route) {
      return false; // No hay ruta que coincida
    }

    // Obtener la ruta activa
    const activeRouteSnapshot = this.router.routerState.snapshot.root;
    // Verificar si la ruta coincide con la ruta activa
    return this.isRouteActive(route, activeRouteSnapshot);
  }

  private isRouteActive(route: Route, activeRouteSnapshot: ActivatedRouteSnapshot): boolean {
    // Comparar por la routeConfig, que define la configuración de la ruta
    if (activeRouteSnapshot.routeConfig === route) {
      return true;
    }

    // Recursivamente verificar en los hijos si hay coincidencias
    for (const childSnapshot of activeRouteSnapshot.children) {
      if (this.isRouteActive(route, childSnapshot)) {
        return true;
      }
    }

    return false;
  }

  /** Guard funcional o, por compatibilidad, clase con `canActivate`/`canActivateChild`. */
  private runGuard(
    guard: unknown,
    method: GuardMethod,
    route: ActivatedRouteSnapshot,
    state: RouterStateSnapshot,
  ): Observable<GuardResult> {
    return runInInjectionContext(this.injector, () => {
      const instance = this.injector.get(guard as any, null, { optional: true }) as Record<GuardMethod, any> | null;
      const result =
        instance && typeof instance[method] === 'function'
          ? instance[method](route, state)
          : (guard as (route: ActivatedRouteSnapshot, state: RouterStateSnapshot) => unknown)(route, state);
      return toObservable(result);
    });
  }

  /** Cadena de rutas, de la raíz a la más específica, que casa con la URL; vacía si no casa ninguna. */
  private matchChain(urlSegments: string[], routes: Route[], parentParams: Params): MatchedRoute[] {
    for (const route of routes) {
      if (!route.path) {
        continue;
      }
      const routeSegments = route.path.split('/');
      const params = this.matchSegments(routeSegments, urlSegments);
      if (!params) {
        continue;
      }
      const allParams = { ...parentParams, ...params };
      const matched = { route, snapshot: this.snapshot(route, urlSegments.slice(0, routeSegments.length), allParams) };
      const remaining = urlSegments.slice(routeSegments.length);

      // Si hay rutas hijas, buscar en ellas; si ninguna casa, la ruta actual es la más específica
      if (route.children && remaining.length) {
        const children = this.matchChain(remaining, route.children, allParams);
        if (children.length) {
          return [matched, ...children];
        }
      }
      return [matched];
    }
    return [];
  }

  /** Parámetros de la ruta si casa con el principio de la URL; null si no casa. */
  private matchSegments(routeSegments: string[], urlSegments: string[]): Params | null {
    const params: Params = {};
    const matches = routeSegments.every((segment, index) => {
      const value = urlSegments[index];
      if (segment.startsWith(':')) {
        params[segment.substring(1)] = value;
        return value !== undefined && value !== '';
      }
      return segment === value;
    });
    return matches ? params : null;
  }

  private snapshot(route: Route, segments: string[], params: Params): ActivatedRouteSnapshot {
    return Object.assign(new ActivatedRouteSnapshot(), {
      url: segments.map((path) => new UrlSegment(path, {})),
      params,
      queryParams: {},
      fragment: null,
      data: { ...route.data },
      outlet: PRIMARY_OUTLET,
      component: route.component ?? null,
    });
  }
}

function toObservable(result: unknown): Observable<GuardResult> {
  if (isObservable(result)) {
    return result as Observable<GuardResult>;
  }
  if (result instanceof Promise) {
    return from(result as Promise<GuardResult>);
  }
  return of(result as GuardResult);
}
